sys_script_include.script:
var grcPortalUtils = Class.create();
grcPortalUtils.prototype = {
    initialize: function() {
    },

	getImmediateTasks: function(filter) {
var dateLast = new GlideDateTime();
var dur;
var dateStatus;
var list=[];
var gr = new GlideRecordSecure('planned_task');
gr.addEncodedQuery('sys_class_name=sn_grc_issue^stateIN1,2,5^NQsys_class_name=sn_grc_task^stateIN1,2,8^NQsys_class_name=sn_compliance_policy_exception^stateIN1,2');
// gr.addQuery('assigned_to', gs.getUserID());
gr.addEncodedQuery(filter);
gr.query();
while (gr.next()) {
	dateStatus = 'none';
	var pTask = {};
	if (!gr.due_date.nil()) {
		dur = GlideDateTime.subtract (new GlideDateTime(gr.getValue ('due_date')), dateLast);
		if(dur.getDayPart() >= 0) dateStatus = 'Overdue';
		if(dur.getDayPart() >= -14 && dur.getDayPart() < 0) dateStatus = 'Pending';

	}
	else {
		dur = GlideDateTime.subtract (new GlideDateTime(gr.getValue ('sys_created_on')), dateLast);
		if(dur.getDayPart() >=30) dateStatus = 'Not Started';
	}

	if(dateStatus != 'none') {
		pTask.sysid = gr.sys_id +'';
		pTask.number = gr.number + '';
		pTask.taskType = gr.getDisplayValue('sys_class_name');
		pTask.desc = gr.description+ '';
		pTask.created = gr.sys_created_on + '';
		pTask.dueDate = gr.due_date + '';
		pTask.dateStatus = dateStatus;
		pTask.table=gr.sys_class_name + '';

		list.push(pTask);
	}

}
		return list;
	},
    type: 'grcPortalUtils'
};
